import{_ as a}from"./chunks/daily-2026-08-11-governed-connector-action-handoff-figure.BulGsqYY.js";import{_ as r,C as o,o as i,c as n,E as d,a2 as c}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"连接器动作需要受治理的权威交接","description":"","frontmatter":{"title":"连接器动作需要受治理的权威交接","date":"2026-08-11","column":"industry-architecture","category":"daily","summary":"Connector-mediated Action 不应被压缩成一次 tool call 的成功或失败，而应明确区分可用性观察、动作资格、用户或角色授权、Provider 提交、Provider 确认结果以及交接后的记录托管。","sources":["research/analysis/Q-20260811-02-connector-action-handoff.md","research/reading/Q-20260811-02-restaurant-reservation-action-handoff.md"],"item_id":"Q-20260811-02","lifecycle":"Published","source_research_object":"research/analysis/Q-20260811-02-connector-action-handoff.md","source_reading_result":"research/reading/Q-20260811-02-restaurant-reservation-action-handoff.md","cover":"/assets/covers/daily-2026-08-11-governed-connector-action-handoff.webp","visualization":"/assets/covers/daily-2026-08-11-governed-connector-action-handoff-figure.svg","visualization_decision":"Required — 独立权威交接编辑性题图 + 独立动作生命周期解释图","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"zh/industry/2026-08-11-governed-connector-action-handoff.md","filePath":"zh/industry/2026-08-11-governed-connector-action-handoff.md","lastUpdated":1786455324000}'),l={name:"zh/industry/2026-08-11-governed-connector-action-handoff.md"};function s(h,e,p,u,m,f){const t=o("ArticleCover");return i(),n("div",null,[d(t,{image:"/assets/covers/daily-2026-08-11-governed-connector-action-handoff.webp",kicker:"行业架构 · 每日研究",title:"连接器动作需要受治理的权威交接",summary:"Connector-mediated Action 不应被压缩成一次 tool call 的成功或失败，而应明确区分可用性观察、动作资格、用户或角色授权、Provider 提交、Provider 确认结果以及交接后的记录托管。",version:"Q-20260811-02",status:"Daily Runtime V5 · 2026-08-11",languageHref:"/en/industry/2026-08-11-governed-connector-action-handoff",languageLabel:"English"}),e[0]||(e[0]=c('<h1 id="连接器动作需要受治理的权威交接" tabindex="-1">连接器动作需要受治理的权威交接 <a class="header-anchor" href="#连接器动作需要受治理的权威交接" aria-label="Permalink to &quot;连接器动作需要受治理的权威交接&quot;">​</a></h1><p>Agent 可以看到一个实时机会，却不一定拥有完成后续交易的权威。ChatGPT 的餐厅预约能力把这个边界展示得很清楚：推荐、实时可用性、动作资格、预约提交和最终预约记录，可能属于不同阶段，甚至属于不同系统。</p><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>OpenAI 官方文档说明，ChatGPT 可以展示来自受支持第三方 Provider 的餐厅预约可用时间；只有当餐厅能够匹配到受支持的预约列表时，才会出现 Reserve 动作。进入预约流程后，用户仍然可以检查和修改人数、日期、时间等信息，然后再提交。预约完成后，第三方 Provider 才是确认、修改、取消以及账户问题的权威记录系统。</p><p>Research Center 的判断是：Connector Action 应当建模为<strong>权威交接</strong>，而不是一个 <code>tool_call -&gt; success</code> 状态。一个可治理的动作生命周期至少应该区分：<code>Availability Observation → Action Eligibility → Authorization → Provider Submission → Provider-confirmed Outcome → External Custody</code>。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>主要一手证据来自 OpenAI 官方文档：</p><ul><li>ChatGPT Release Notes：<a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/6825453-chatgpt-release-notes</a></li><li>ChatGPT Search Help：<a href="https://help.openai.com/en/articles/9237897-chatgpt-search" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/9237897-chatgpt-search</a></li></ul><p>同日 Reading Result 记录了 2026-08-10 的预约能力更新，以及 Reserve Button、用户确认、Provider 确认和预约后归属边界。本次 Production 不推断官方没有披露的 Connector Protocol 或 API Guarantee。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>已记录的产品行为把“推荐”和“动作”分开。一个餐厅可以值得推荐，但如果 ChatGPT 无法把它匹配到受支持的预约 Provider，就不会出现 Reserve 动作。因此 Recommendation Eligibility 与 Action Eligibility 是不同状态。</p><p>可用时间本身也是时效性观察。官方文档明确提醒 Availability 会变化，所以显示一个时间槽并不等于已经形成持久承诺。</p><p>当 Reserve 可用时，用户进入预约流程，并可以在提交前调整信息。预约完成之后，ChatGPT 不保存预约作为权威记录；后续确认、修改、取消以及 Provider Account 问题都由外部预约 Provider 负责。</p><p>产品入口本身也是执行策略的一部分。官方说明该能力适用于受支持的 ChatGPT Surface，同时明确排除 ChatGPT Work。这说明是否可执行不仅由模型能力决定，还受到 Product Surface、Region、Identity 和 Provider Match 等政策输入约束。</p><p><img src="'+a+'" alt="连接器动作权威交接生命周期"></p><p><em>图 1：连接器动作从可用性观察经过资格、授权与提交，最终把结果与记录托管交给 Provider。来源：Research Center 基于文中引用的一手资料综合绘制。</em></p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>权威问题</th><th>典型权威主体</th><th>证据类型</th></tr></thead><tbody><tr><td>Availability Observation</td><td>“现在能看到这个时间吗？”</td><td>Reservation Provider 数据，经 ChatGPT 展示</td><td>官方产品文档</td></tr><tr><td>Action Eligibility</td><td>“这个结果能否出现 Reserve？”</td><td>Product / Provider Match + Surface Policy</td><td>官方文档</td></tr><tr><td>Authorization</td><td>“是否允许提交这个预约？”</td><td>用户确认或显式角色策略</td><td>官方用户流程 + Research Center 泛化</td></tr><tr><td>Provider Submission</td><td>“请求是否真正发送给 Provider？”</td><td>Connector / Provider Boundary</td><td>Research Center 架构模型；协议未公开</td></tr><tr><td>Provider-confirmed Outcome</td><td>“Provider 是否接受交易？”</td><td>Reservation Provider</td><td>官方确认与支持边界</td></tr><tr><td>Post-booking Custody</td><td>“之后由谁修改或取消？”</td><td>Reservation Provider</td><td>官方文档</td></tr></tbody></table><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>当 Connector Platform 把每一个成功的 Tool Return 都当成业务结果时，系统很容易产生错误语义。工具可以返回当前 Availability，却没有完成任何预约；它可以打开预约动作，但用户还没有授权提交；它可以提交请求，但 Provider 还没有确认接受；即使预约已完成，后续生命周期也可能已经转移到外部系统。</p><p>因此需要两组治理机制。第一，每一个有副作用的 Skill 都应该公开 Machine-readable Authority Descriptor：Observe、Propose、Submit 和 Lifecycle-manage 是四种不同能力。第二，每一个跨系统动作都应该产生 Handoff Receipt，至少记录 Provider Identity、内部 Occurrence ID、提交参数、Provider Confirmation/Error Reference 和当前 Custody Owner。</p><p>System of Record 的边界也应该直接体现在 UI 中。<code>Available</code>、<code>Actionable</code>、<code>Submitted</code>、<code>Confirmed</code> 不能被压缩成同一个“成功”标记。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对于数字员工，所有副作用型 Connector Skill 应明确声明它属于 Read-only、Proposal-only、Submit-capable，还是能够管理后续生命周期。进入 Provider Submission 的边界必须由人类确认或显式 Role Policy 控制。</p><p>对于 CodeFlowMu，外部 Connector Action 应表现为受治理的 TASK / Tool Transition，而不是普通 Tool Return Text。内部 Task ID 与外部 Provider Transaction ID 应分开保存，Runtime Timeline 应区分 Candidate、Actionable、Submitted、Confirmed 等状态，避免把“看到机会”误认为“已经完成动作”。</p><p>对于 TMPA，这一案例是 Authority Transfer、Custody 与 Cross-system Evidence 的有效工程研究输入，但当前产品文档没有给出可以直接标准化的通用 Connector Protocol。</p><h2 id="边界与不确定性" tabindex="-1">边界与不确定性 <a class="header-anchor" href="#边界与不确定性" aria-label="Permalink to &quot;边界与不确定性&quot;">​</a></h2><p>官方资料没有披露 Connector API、Authentication Model、Cache Strategy、Freshness SLA、Duplicate-submit Protection、Payment/Deposit Handling、Provider Login Flow 或 Consistency Guarantee。因此当前证据能够建立的是用户可见的权威边界，而不是完整交易协议。</p><h2 id="后续研究" tabindex="-1">后续研究 <a class="header-anchor" href="#后续研究" aria-label="Permalink to &quot;后续研究&quot;">​</a></h2><p>通用 Agent Runtime 需要定义一份最小 Handoff Receipt，并明确在真正提交之前如何重新验证已变旧的 Availability；当一个 Business 被多个 Provider 同时表示时，也需要定义本次动作的权威 Provider 选择规则。对于数字员工，还需要明确哪些岗位可以自主 Proposal、Submit、Modify 或 Cancel，哪些动作必须由人类确认。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>题图位于文章头部，以两个权威域在受控边界交接单一交易载体表现权威转移；嵌入“观察”部分的解释图呈现完整六阶段交接生命周期。两张图均为 Research Center 原创，不包含人为制造的量化数据。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ol><li>OpenAI，ChatGPT Release Notes，2026-08-10 餐厅预约可用性更新：<a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/6825453-chatgpt-release-notes</a></li><li>OpenAI，ChatGPT Search Help，Reserve 动作与预约流程说明：<a href="https://help.openai.com/en/articles/9237897-chatgpt-search" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/9237897-chatgpt-search</a></li><li>Research Center Research Object：<code>research/analysis/Q-20260811-02-connector-action-handoff.md</code></li><li>Research Center Reading Result：<code>research/reading/Q-20260811-02-restaurant-reservation-action-handoff.md</code></li></ol><blockquote><p>发布状态：已通过 Publication 门禁并正式发布；正文内容未对 Production Candidate 进行实质性改写。</p></blockquote>',35))])}const g=r(l,[["render",s]]);export{b as __pageData,g as default};
